class Solution:
    def numberOfRounds(self, loginTime: str, logoutTime: str) -> int:
        def minutes(t):
            return int(t[:2]) * 60 + int(t[3:])

        start, end = minutes(loginTime), minutes(logoutTime)
        if end <= start:
            end += 1440
        count = 0
        for k in range(96):
            for s in (k * 15, k * 15 + 1440):
                if s >= start and s + 15 <= end:
                    count += 1
        return count

