class Solution {
public:
    int numberOfRounds(string loginTime, string logoutTime) {
        auto toMin = [](const string& t) {
            return stoi(t.substr(0, 2)) * 60 + stoi(t.substr(3));
        };
        int start = toMin(loginTime), end = toMin(logoutTime);
        if (end <= start) end += 1440;
        int cnt = 0;
        for (int k = 0; k < 96; ++k)
            for (int shift : {0, 1440}) {
                int s = k * 15 + shift;
                if (s >= start && s + 15 <= end) ++cnt;
            }
        return cnt;
    }
};

